/* lazysite-app.js (SM1155, SM1197): registers the app's service worker.
 *
 * The engine adds this script to a page inside an app's scope, with the worker's
 * address and scope as data attributes. The worker itself is generated by the
 * engine (lazysite-processor/app.pm); this only asks the browser to install it.
 * It reads nothing from the page and stores nothing. A browser without service
 * workers, or a refusal, leaves the page exactly as it was - but no longer
 * silently: the reason goes to the console as a warning (SM1197), because a
 * registration that fails for a missing file or an insecure origin otherwise
 * leaves no trace at all.
 *
 * With data-ls-app-update="wait" (app_update: wait) a new worker is held until
 * the page asks. When one is ready the script dispatches a `lazysite-app-update`
 * event on window; event.detail.apply() tells it to take over, and the page then
 * reloads once, because only the page knows when no input would be lost:
 *
 *   window.addEventListener('lazysite-app-update', function (e) {
 *     if (confirm('A new version is ready. Reload?')) e.detail.apply();
 *   });
 *
 * A page that adds its listener after the event can read window.lazysiteApp.apply,
 * which is set while an update is waiting. */
(function () {
  'use strict';
  var TAG = 'lazysite-app: ';
  var s = document.querySelector('script[data-ls-app-sw]');
  if (!s) return;
  var sw = s.getAttribute('data-ls-app-sw');
  var scope = s.getAttribute('data-ls-app-scope');
  if (!sw || !scope) return;

  if (!('serviceWorker' in navigator)) {
    console.warn(TAG + (window.isSecureContext === false
      ? 'service workers need a secure context (https, or http://localhost); this page is on an insecure origin, so the app cannot install or open offline'
      : 'this browser has no service workers, so the app cannot install or open offline'));
    return;
  }

  /* The browser's message says what went wrong; this says what to look at. */
  function why(err) {
    var m = (err && err.message) || String(err);
    if ((err && err.name === 'SecurityError') || /insecure/i.test(m)) {
      return 'the origin is not secure: a service worker needs https or http://localhost (' + m + ')';
    }
    if (/\b404\b|bad HTTP response/i.test(m)) {
      return sw + ' answered 404: check that app_name is set, that app_scope is ' + scope + ', and that the page cache was invalidated after turning the app on (' + m + ')';
    }
    if (/script|syntax|evaluation|MIME/i.test(m)) {
      return sw + ' is not a working script: it failed to load or has a script error (' + m + ')';
    }
    return m;
  }

  var waiting = s.getAttribute('data-ls-app-update') === 'wait';
  var asked = false;

  function offer(worker) {
    var apply = function () {
      asked = true;
      worker.postMessage({ type: 'skip-waiting' });
    };
    window.lazysiteApp = window.lazysiteApp || {};
    window.lazysiteApp.apply = apply;
    window.dispatchEvent(new CustomEvent('lazysite-app-update', { detail: { apply: apply } }));
  }

  navigator.serviceWorker.register(sw, { scope: scope }).then(function (reg) {
    if (!waiting) return;
    /* Only a swap this page asked for reloads it: another tab's update must not
       reload a form that is half filled in here. */
    navigator.serviceWorker.addEventListener('controllerchange', function () {
      if (!asked) return;
      asked = false;
      window.location.reload();
    });
    if (reg.waiting && navigator.serviceWorker.controller) offer(reg.waiting);
    reg.addEventListener('updatefound', function () {
      var found = reg.installing;
      if (!found) return;
      found.addEventListener('statechange', function () {
        if (found.state === 'installed' && navigator.serviceWorker.controller) offer(reg.waiting || found);
      });
    });
  }).catch(function (err) {
    console.warn(TAG + 'the service worker did not register: ' + why(err));
  });
})();
